"""Track-scoped V2.0.7 Practice workspace browser UI."""
from __future__ import annotations


def practice_hub_page_html() -> str:
    return r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Race Engineer Practice</title><style>
:root{--bg:#080d12;--panel:#101820;--panel2:#0b1219;--line:#273746;--text:#eef6fb;--muted:#8395a8;--cyan:#4dd9ff;--green:#2ed486;--red:#ff5967;--amber:#f5bd4d;--blue:#7697ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Segoe UI,Arial,sans-serif;font-size:14px}.wrap{padding:18px}.top{display:flex;justify-content:space-between;align-items:center;gap:12px}.eyebrow{color:var(--cyan);font-size:10px;font-weight:900;letter-spacing:.09em}.top h1{margin:3px 0 0;font-size:28px}.sub,.small{color:var(--muted);font-size:12px}.controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap}select,button{background:#0d151d;color:var(--text);border:1px solid var(--line);border-radius:7px;padding:8px 10px}button{cursor:pointer}.panel{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:14px;margin-top:12px}.scope{display:grid;grid-template-columns:2fr repeat(3,1fr);gap:8px}.card{background:var(--panel2);border:1px solid var(--line);border-radius:9px;padding:11px}.k{color:var(--muted);font-size:10px;font-weight:900;letter-spacing:.07em}.big{font-size:28px;font-weight:900;margin-top:3px}.pill{display:inline-flex;align-items:center;justify-content:center;align-self:flex-start;flex:0 0 auto;width:auto;height:auto;min-width:0;white-space:nowrap;border:1px solid #246448;color:var(--green);border-radius:999px;padding:5px 9px;font-size:10px;font-weight:900;line-height:1.2}.pill.provisional{border-color:#7a6120;color:var(--amber)}.pill.clear{border-color:#2d6684;color:var(--cyan)}.pill.insufficient{border-color:#5a6570;color:var(--muted)}.focusGrid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.focus{padding:12px;border-radius:9px;border:1px solid var(--line);border-left:4px solid var(--red);background:linear-gradient(135deg,#211319,#101820 55%)}.focus.secondary{border-left-color:var(--amber);background:linear-gradient(135deg,#201b10,#101820 55%)}.focus.immediate{border-left-color:var(--cyan);background:linear-gradient(135deg,#0e1c24,#101820 55%)}.issue{font-size:17px;font-weight:900;margin:5px 0}.badge{display:inline-block;padding:3px 7px;border-radius:999px;background:#10323b;color:var(--cyan);font-size:10px;font-weight:900}.badge.rec{background:#103626;color:var(--green)}.phases{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}.phase{background:var(--panel2);border:1px solid var(--line);border-top:3px solid var(--blue);border-radius:9px;padding:10px;min-height:165px}.phase:nth-child(2){border-top-color:var(--red)}.phase:nth-child(3){border-top-color:var(--cyan)}.phase:nth-child(4){border-top-color:var(--amber)}.phase:nth-child(5){border-top-color:var(--green)}.phase h3{margin:6px 0;font-size:16px}.timer{display:grid;grid-template-columns:200px 1fr auto;gap:10px;align-items:center}.clock{font-size:26px;font-weight:900}.bar{height:10px;background:#1b2b38;border-radius:8px;overflow:hidden}.fill{height:100%;width:0;background:var(--cyan)}.resolved{display:grid;grid-template-columns:repeat(2,1fr);gap:6px}.resolved>div{padding:8px;background:#0b1219;border:1px solid #1f2b36;border-radius:7px}.ai{border-color:#66521f;background:linear-gradient(135deg,#16140d,#101820 60%)}.aiOut{white-space:pre-wrap;line-height:1.5;margin-top:10px}.empty{color:var(--muted);padding:22px;text-align:center}@media(max-width:1000px){.scope,.phases{grid-template-columns:1fr 1fr}.focusGrid{grid-template-columns:1fr}.timer{grid-template-columns:1fr}.resolved{grid-template-columns:1fr}}</style></head><body><div class=wrap>
<div class=top><div><div class=eyebrow>V2.0.7 · TRACK PRACTICE</div><h1>PRACTICE</h1><div class=sub>Track-level practice planning across all stored live sessions for the selected driver.</div></div><div class=controls><label>DRIVER <select id=driver></select></label><label>TRACK <select id=track></select></label><button id=refresh>REFRESH</button></div></div>
<div id=content><div class="panel empty">Loading track practice evidence…</div></div>
</div><script>
const $=id=>document.getElementById(id),num=v=>typeof v==='number'&&Number.isFinite(v),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let overview=null,currentDriver=null,currentTrack=null,currentReference=null,currentCondition=null,timerHandle=null;
function tf(s){if(!num(s))return'--';let m=Math.floor(s/60),x=s-m*60;return `${m}:${x.toFixed(3).padStart(6,'0')}`}
function localStamp(v){if(!v)return'--';try{return new Intl.DateTimeFormat(undefined,{timeZone:overview?.time_zone||'UTC',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false,timeZoneName:'short'}).format(new Date(v))}catch(e){return String(v).replace('T',' ').slice(0,19)}}
function dedupeImmediate(rows){let out=[];for(let x of (rows||[])){if(!x)continue;let c=x.corner_id,cost=num(x.measured_time_cost_s)?Number(x.measured_time_cost_s):null;let hit=out.find(y=>String(y.corner_id)===String(c)&&num(cost)&&num(y.measured_time_cost_s)&&Math.abs(Number(y.measured_time_cost_s)-cost)<0.002);if(hit){let labels=new Set([hit.issue_label||hit.issue_code,x.issue_label||x.issue_code].filter(Boolean));hit=Object.assign(hit,{issue_label:[...labels].join(' / ')});out[out.findIndex(y=>String(y.corner_id)===String(c)&&num(y.measured_time_cost_s)&&Math.abs(Number(y.measured_time_cost_s)-cost)<0.002)]=hit}else out.push(Object.assign({},x))}return out}
function qlabel(x){return String(x||'unknown').replaceAll('_',' ')}
function focus(x,cls=''){if(!x)return'<div class=empty>No current measured issue.</div>';let rec=x.authority==='recurring_pattern';return `<div class="focus ${cls}"><div class=small>T${esc(x.corner_id??'--')} · ${esc(x.phase||'')}</div><div class=issue>${esc(x.issue_label||x.issue_code||'Measured issue')}</div><span class="badge ${rec?'rec':''}">${rec?'RECURRING':'CURRENT'}</span><div class=small style="margin-top:8px">Measured cost ${num(x.measured_time_cost_s)?Number(x.measured_time_cost_s).toFixed(3)+' s':'N/A'} · confidence ${num(x.confidence)?Math.round(x.confidence*100)+'%':'N/A'} · ${x.history_sessions||x.session_repeat_count||x.repeat_count||1} historical observation(s) · ${esc(x.trend||'')}</div></div>`}
function timerKey(){return `race.practice.track.timer.${currentDriver||'x'}.${currentTrack||'x'}`};function readTimer(){try{return Object.assign({elapsed:0,running:false,startedAt:null},JSON.parse(localStorage.getItem(timerKey())||'{}'))}catch(e){return{elapsed:0,running:false,startedAt:null}}}function elapsed(s){let e=Number(s.elapsed||0);if(s.running&&s.startedAt)e+=(Date.now()-s.startedAt)/1000;return Math.min(1200,Math.max(0,e))}function renderTimer(){if(!$('clock'))return;let s=readTimer(),e=elapsed(s),m=Math.floor(e/60),ss=Math.floor(e%60);$('clock').textContent=`${String(m).padStart(2,'0')}:${String(ss).padStart(2,'0')} / 20:00`;$('fill').style.width=(e/12)+'%';if(e>=1200&&s.running){s.running=false;s.elapsed=1200;s.startedAt=null;localStorage.setItem(timerKey(),JSON.stringify(s))}}
function startTimer(){let s=readTimer();if(elapsed(s)>=1200)s={elapsed:0,running:false,startedAt:null};if(!s.running){s.elapsed=elapsed(s);s.running=true;s.startedAt=Date.now();localStorage.setItem(timerKey(),JSON.stringify(s))}if(!timerHandle)timerHandle=setInterval(renderTimer,1000);renderTimer()}function pauseTimer(){let s=readTimer();s.elapsed=elapsed(s);s.running=false;s.startedAt=null;localStorage.setItem(timerKey(),JSON.stringify(s));renderTimer()}function resetTimer(){localStorage.removeItem(timerKey());renderTimer()}
async function loadOverview(){let q=new URLSearchParams();if(currentDriver)q.set('driver',currentDriver);let d=await (await fetch('/api/practice/overview?'+q,{cache:'no-store'})).json();overview=d;currentDriver=d.driver?.id||currentDriver;$('driver').innerHTML=(d.profiles||[]).map(x=>`<option value="${x.id}" ${String(x.id)===String(currentDriver)?'selected':''}>${esc(x.name||'Driver')}</option>`).join('');let tracks=(d.tracks||[]).map(x=>x.track);if(!currentTrack||!tracks.includes(currentTrack))currentTrack=tracks[0]||null;$('track').innerHTML=tracks.map(x=>`<option ${x===currentTrack?'selected':''}>${esc(x)}</option>`).join('');if(currentTrack)await loadTrack();else $('content').innerHTML='<div class="panel empty">No stored live track sessions for this Driver.</div>'}
async function loadTrack(){let u=`/api/practice/track?track=${encodeURIComponent(currentTrack)}&driver=${encodeURIComponent(currentDriver||'')}`;if(currentReference)u+=`&reference=${encodeURIComponent(currentReference)}`;if(currentCondition)u+=`&condition=${encodeURIComponent(currentCondition)}`;let d=await (await fetch(u,{cache:'no-store'})).json();if(!currentReference&&d.selected_reference?.id)currentReference=d.selected_reference.id;if(!currentCondition&&d.selected_condition)currentCondition=d.selected_condition;render(d)}
function render(d){let p=d.practice_plan||{},sum=p.summary||{},pri=p.primary_focus,sec=p.secondary_focus,nf=dedupeImmediate(p.next_lap_focus||[]),resolved=p.resolved_or_not_current||[],latest=(d.sessions||[]).filter(x=>x.practice_usable).at(-1)||(d.sessions||[]).at(-1)||{},st=p.status||'insufficient_evidence',status=st==='available'?'READY':st==='provisional'?'PROVISIONAL':st==='clear'?'NO CURRENT ISSUE':'INSUFFICIENT',pillClass=st==='provisional'?'provisional':st==='clear'?'clear':st==='available'?'':'insufficient';let refs=d.reference_options||[],sel=d.selected_reference||null,qs=d.quality_summary||{},qreasons=qs.reason_counts||[],qdetails=qs.excluded_lap_details||[];if(sel?.id)currentReference=sel.id;if(d.selected_condition)currentCondition=d.selected_condition;let refSelect=`<label>PRACTICE REFERENCE <select id=practiceRef>${refs.map(x=>`<option value="${esc(x.id)}" ${String(x.id)===String(currentReference)?'selected':''}>${esc(x.label||'Rival reference')} · ${tf(x.lap_time_s)}</option>`).join('')}</select></label>`;let conds=d.condition_options||[],conditionSelect=`<label>TRACK CONDITION <select id=practiceCondition>${conds.map(x=>`<option value="${esc(x.id)}" ${String(x.id)===String(currentCondition)?'selected':''}>${esc(x.label)} · ${x.session_count} session${x.session_count===1?'':'s'}</option>`).join('')}</select></label>`;let included=(p.session_policy?.included||[]).map(x=>String(x).replaceAll('_',' ')).join(' · '),excluded=(p.session_policy?.excluded||[]).map(x=>String(x).replaceAll('_',' ')).join(' · ');$('content').innerHTML=`<div class=panel><div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px"><div><div class=eyebrow>PRACTICE SCOPE</div><h2 style="margin:3px 0">${esc(d.track||currentTrack)} · ${esc(String(currentCondition||'unknown').toUpperCase())}</h2><div class=small>All stored live sessions for this driver on this track are considered under the Practice session policy. Track Practice combines eligible evidence across allowed live session types for this driver and track. Dry, wet and unknown conditions are kept separate. The selected same-condition Practice Reference is the benchmark/confirmation authority; older evidence from another or unknown reference remains provisional instead of disappearing.</div><div class=controls style="margin-top:10px">${refSelect}${conditionSelect}</div><div class=small style="margin-top:8px">Included: ${esc(included||'time trial · free practice · qualifying')} · Excluded: ${esc(excluded||'race · sprint · replay')} · Game VALID and coaching eligibility are separate: quality gates still remove partial, pit, insufficient-sample, traffic, race-control, damage and telemetry-compromised laps from scoring/coaching evidence.</div></div><span class="pill ${pillClass}">${status}</span></div>${p.legacy_reference_notice?`<div class="small" style="margin-top:10px;padding:9px 11px;border:1px solid #7a6120;border-radius:7px;color:var(--amber)">${esc(p.legacy_reference_notice)}</div>`:''}<div class=scope style="margin-top:10px"><div class=card><div class=k>PRACTICE HISTORY · ${esc(String(currentCondition||'unknown').toUpperCase())}</div><div class=big>${d.usable_session_count||0} usable</div><div class=small>${p.baseline_eligible_laps||0} eligible laps · ${d.compatible_session_count||0} verified to selected reference · ${d.legacy_session_count||0} legacy provisional · ${d.weather_excluded_count||0} other-weather · ${d.session_type_excluded_count||0} excluded session type · latest ${esc(latest.created_display||localStamp(latest.created_utc))}</div></div><div class=card><div class=k>PRACTICE BENCHMARK</div><div class=big>${tf(sel?.lap_time_s)}</div><div class=small>${esc(sel?.label||"Select a rival reference")} · ${esc(String(currentCondition||'unknown').toUpperCase())}</div></div><div class=card><div class=k>MAX TIMED LAPS</div><div class=big>${p.estimated_laps??'--'}</div><div class=small>20 min / best usable pace for this condition; excludes pit/out-lap time</div></div><div class=card><div class=k>CURRENT FOCUS COST</div><div class=big>${num(sum.current_focus_cost_s)?sum.current_focus_cost_s.toFixed(3)+' s':st==='clear'?'0.000 s':'N/A'}</div><div class=small>${st==='clear'?'no current measured weakness survives verified evidence':'selected current primary issue'}</div></div></div></div>
${(qs.excluded_laps||0)>0?`<div class=panel><div class=eyebrow>WHY VALID LAPS MAY STILL BE EXCLUDED</div><div class=small style="margin-top:6px">F1 lap validity is not the same as coaching-score eligibility. For ${esc(String(currentCondition||'unknown').toUpperCase())}: ${qs.timed_valid_laps??'--'} timed valid · ${qs.eligible_laps??0} coaching-eligible · ${qs.excluded_laps??0} quality-excluded.</div><div class=resolved style="margin-top:9px">${qreasons.length?qreasons.map(x=>`<div><b>${esc(qlabel(x.reason))}</b><div class=small>${x.count} lap${x.count===1?'':'s'}</div></div>`).join(''):'<div class=small>Excluded laps were recorded but no reason breakdown was persisted.</div>'}</div>${qdetails.length?`<div class=small style="margin-top:8px">${qdetails.slice(0,8).map(x=>`L${esc(x.lap??'--')} (${esc(x.session_type||'Session')}): ${esc((x.reasons||[]).map(qlabel).join(', ')||'quality excluded')}`).join(' · ')}</div>`:''}</div>`:''}
<div class=panel><div class=eyebrow>CURRENT TRACK FOCUS</div><div class=focusGrid style="margin-top:9px">${focus(pri)}${focus(sec,'secondary')}</div></div>
<div class=panel><div class=eyebrow>LATEST SESSION · IMMEDIATE</div><div class=focusGrid style="margin-top:9px">${nf.length?nf.slice(0,2).map(x=>focus(x,'immediate')).join(''):'<div class=empty>No immediate next-lap focus in the newest session.</div>'}</div></div>
<div class=panel><div class=eyebrow>20-MINUTE STRUCTURE</div><div class=phases style="margin-top:9px">${(p.phases||[]).map(x=>`<div class=phase><div class=small>${x.start_min}–${x.end_min} MIN</div><h3>${esc(x.name)}</h3><div>${esc(x.goal||'')}</div><div class=small style="margin-top:8px">${esc(x.evidence||'')}</div></div>`).join('')}</div></div>
<div class=panel><div class=timer><div><div class=k>PRACTICE TIMER</div><div id=clock class=clock>00:00 / 20:00</div></div><div><div class=k>PROGRESS</div><div class=bar><div id=fill class=fill></div></div></div><div class=controls><button id=start>START</button><button id=pause>PAUSE</button><button id=reset>RESET</button></div></div></div>
<div class=panel><div class=eyebrow>OLDER WEAKNESSES NO LONGER CURRENT</div><div class=small style="margin-bottom:8px">These are kept as history but cannot become the current plan unless they reappear in newer evidence.</div><div class=resolved>${resolved.length?resolved.slice(0,8).map(x=>`<div><b>T${esc(x.corner_id)} · ${esc(x.issue_label)}</b><div class=small>${x.history_sessions} historical session(s) · last cost ${num(x.last_measured_time_cost_s)?x.last_measured_time_cost_s.toFixed(3)+' s':'N/A'}</div></div>`).join(''):'<div class=small>No historical issue has been retired by newer session evidence.</div>'}</div></div>
<div class="panel ai"><div class=eyebrow>LOCAL AI · EXPLANATION ONLY</div><h2 style="margin:4px 0">AI PRACTICE BRIEF</h2><div class=small>Uses the deterministic track-level plan only. It cannot select different issues or alter measurements.</div><div class=small id=aiEvidence>${pri?`Deterministic input: T${esc(pri.corner_id)} · ${esc(pri.issue_label||pri.issue_code)}${sec?` · secondary T${esc(sec.corner_id)} ${esc(sec.issue_label||sec.issue_code)}`:''}`:st==='clear'?'Deterministic input: no current measured issue in newest-session authority.':'Deterministic input: insufficient current focus evidence.'}</div><div id=aiOut class=aiOut>Generate a concise track-practice brief.</div><button id=aiBtn style="margin-top:10px">GENERATE PRACTICE BRIEF</button></div>`;$('start').onclick=startTimer;$('pause').onclick=pauseTimer;$('reset').onclick=resetTimer;$('aiBtn').onclick=ai;let pr=$('practiceRef');if(pr)pr.onchange=async()=>{currentReference=pr.value;localStorage.setItem(`race.practice.reference.${currentDriver}.${currentTrack}.${currentCondition||'unknown'}`,currentReference);await loadTrack()};let pc=$('practiceCondition');if(pc)pc.onchange=async()=>{currentCondition=pc.value;localStorage.setItem(`race.practice.condition.${currentDriver}.${currentTrack}`,currentCondition);currentReference=localStorage.getItem(`race.practice.reference.${currentDriver}.${currentTrack}.${currentCondition}`)||null;await loadTrack()};renderTimer()}
async function ai(){let b=$('aiBtn'),o=$('aiOut');b.disabled=true;o.textContent='Generating with local Ollama…';try{let r=await fetch('/api/performance/ai-summary',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scope:'practice_track',track:currentTrack,driver:currentDriver,reference:currentReference,condition:currentCondition})}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'unavailable');o.textContent=d.summary}catch(e){o.textContent='AI brief unavailable: '+e.message+' Deterministic track plan remains authoritative.'}finally{b.disabled=false}}
$('driver').onchange=async()=>{currentDriver=$('driver').value;currentTrack=null;localStorage.setItem('race.practice.driver',currentDriver);await loadOverview()};$('track').onchange=async()=>{currentTrack=$('track').value;localStorage.setItem('race.practice.track',currentTrack);currentCondition=localStorage.getItem(`race.practice.condition.${currentDriver}.${currentTrack}`);currentReference=currentCondition?localStorage.getItem(`race.practice.reference.${currentDriver}.${currentTrack}.${currentCondition}`):null;await loadTrack()};$('refresh').onclick=loadOverview;currentDriver=localStorage.getItem('race.practice.driver');currentTrack=localStorage.getItem('race.practice.track');if(currentDriver&&currentTrack){currentCondition=localStorage.getItem(`race.practice.condition.${currentDriver}.${currentTrack}`);if(currentCondition)currentReference=localStorage.getItem(`race.practice.reference.${currentDriver}.${currentTrack}.${currentCondition}`)}loadOverview();
</script></body></html>'''
